<script setup lang="ts">
import { ref,reactive,computed,watch,onBeforeUnmount } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import 'element-plus/es/components/message-box/style/css'
import { getArticle,type AdminArticle } from '@/api/admin-articles'
import { adminWriting,createWriting,saveWriting,writingStatus,type AdminWriting,type WritingContent } from '@/api/writing'
import { useFormFeedback } from '@/feedback/useFormFeedback'
import FieldError from '@/components/FieldError.vue'
import FormFeedback from '@/components/FormFeedback.vue'
import { notifySuccess } from '@/feedback/notify'
import { getGeneration,onRemoteIdentityChange } from '@/auth/token-session'
import { ApiError } from '@/api/client'
const route=useRoute(),router=useRouter(),article=ref<AdminArticle>(),items=ref<AdminWriting[]>([]),selected=ref<AdminWriting>(),busy=ref(false),loading=ref(true),pageError=ref(''),invalidated=ref(false)
const defaults=()=>({expression:'',meaningZh:'',keyPhrases:'',structure:'',exampleEn:'',exampleZh:'',scenarios:'',sortOrder:0})
const input=reactive(defaults()),snapshot=ref(JSON.stringify(defaults())),dirty=computed(()=>snapshot.value!==JSON.stringify(input))
const conflict=ref(false)
const fieldNames=['expression','meaningZh','keyPhrases','structure','exampleEn','exampleZh','scenarios','sortOrder'] as const
const labels:Record<string,string>={expression:'核心英文表达',meaningZh:'中文释义',keyPhrases:'重点词组（每行一项，最多8项）',structure:'句型结构',exampleEn:'完整英文例句',exampleZh:'例句中文翻译',scenarios:'适用场景（每行一项，最多8项）',sortOrder:'展示顺序'}
const limits:Record<string,number>={expression:300,meaningZh:600,keyPhrases:1000,structure:1000,exampleEn:2000,exampleZh:2000,scenarios:1000}
const feedback=useFormFeedback({fields:fieldNames,onPageError:value=>{pageError.value=value.message}}),{form,panel,fieldErrors,formError}=feedback
const version=computed(()=>typeof route.query.version==='string'?route.query.version:article.value?.publishedVersionId||article.value?.draftVersionId||'')
let ticket=0,disposed=false,controller:AbortController|undefined
function valid(current:number,identity:number){return !disposed&&current===ticket&&identity===getGeneration()&&!invalidated.value}
function fill(item?:AdminWriting){selected.value=item;Object.assign(input,item?{...item.draft,keyPhrases:item.draft.keyPhrases.join('\n'),scenarios:item.draft.scenarios.join('\n')}:defaults());snapshot.value=JSON.stringify(input);feedback.reset();conflict.value=false;pageError.value=''}
async function leave(){if(!dirty.value||invalidated.value)return true;try{await ElMessageBox.confirm('未保存的素材修改将丢失，是否继续？','离开编辑',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',autofocus:false});return true}catch{return false}}
async function reload(){const current=ticket,identity=getGeneration();if(await leave()&&!disposed&&current===ticket&&identity===getGeneration())await load()}
async function select(item?:AdminWriting){const current=ticket,identity=getGeneration();if(busy.value||invalidated.value||!await leave()||!valid(current,identity))return;fill(item)}
async function load(){const current=++ticket,identity=getGeneration();controller?.abort();controller=new AbortController();loading.value=true;busy.value=false;pageError.value='';invalidated.value=false;article.value=undefined;items.value=[];fill();try{const record=await getArticle(String(route.params.id));if(!valid(current,identity))return;article.value=record;const result=await adminWriting(record.id,version.value,controller.signal);if(valid(current,identity))items.value=result}catch(e){if(valid(current,identity))await feedback.fail(e)}finally{if(valid(current,identity))loading.value=false}}
async function save(){if(busy.value||invalidated.value||!article.value)return;if(!feedback.validate()){await feedback.focusError();return}const current=ticket,identity=getGeneration();busy.value=true;const content:WritingContent={...input,keyPhrases:input.keyPhrases.split('\n').map(s=>s.trim()).filter(Boolean),scenarios:input.scenarios.split('\n').map(s=>s.trim()).filter(Boolean)};try{const result=selected.value?await saveWriting(selected.value.id,content,selected.value.lockVersion):await createWriting(article.value.id,version.value,content);if(!valid(current,identity))return;items.value=[...items.value.filter(i=>i.id!==result.id),result];fill(result);notifySuccess('素材草稿已保存')}catch(e){if(valid(current,identity)){conflict.value=e instanceof ApiError&&e.code==='WRITING_CONFLICT';await feedback.fail(e)}}finally{if(valid(current,identity))busy.value=false}}
async function changeStatus(item:AdminWriting,status:'publish'|'unpublish'|'archive'){if(busy.value||dirty.value||invalidated.value)return;const current=ticket,identity=getGeneration();busy.value=true;try{try{await ElMessageBox.confirm(status==='publish'?'确认例句、释义及使用场景已校对？发布后可随对应文章版本公开展示。':status==='archive'?'归档后不再展示素材，记录将保留。':'下架后读者不再看到该素材，草稿和记录保留。',status==='publish'?'发布素材':status==='archive'?'归档素材':'下架素材',{confirmButtonText:'确认',cancelButtonText:'取消',autofocus:false})}catch{return}if(!valid(current,identity))return;const result=await writingStatus(item.id,status,item.lockVersion);if(!valid(current,identity))return;items.value=items.value.filter(i=>i.id!==item.id);if(result)items.value.push(result);if(selected.value?.id===item.id)fill(result||undefined);notifySuccess(status==='publish'?'素材已发布':status==='archive'?'素材已归档':'素材已下架')}catch(e){if(valid(current,identity)){conflict.value=e instanceof ApiError&&e.code==='WRITING_CONFLICT';await feedback.fail(e)}}finally{if(valid(current,identity))busy.value=false}}
function changeVersion(event:Event){const control=event.target as HTMLSelectElement,value=control.value;control.value=version.value;void router.push({path:route.path,query:{version:value}})}
const unsubscribe=onRemoteIdentityChange(()=>{ticket++;controller?.abort();invalidated.value=true;items.value=[];article.value=undefined;fill();pageError.value='账户状态已变化，请重新加载后编辑。';loading.value=false})
watch(()=>[route.params.id,route.query.version],load,{immediate:true});onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);onBeforeUnmount(()=>{disposed=true;ticket++;controller?.abort();unsubscribe()})
</script>
<template><section class="reading-page writing-admin"><header class="reading-page-header"><div><RouterLink class="reading-back" :to="`/admin/articles/${route.params.id}/edit`">← 返回文章编辑</RouterLink><h1>写作素材管理</h1><p>绑定具体文章版本；保存草稿不会替换当前发布内容。</p></div></header><p v-if="loading" role="status">正在加载素材…</p><div v-if="pageError" class="reading-notice" role="alert"><p>{{ pageError }}</p><button type="button" class="button-secondary" @click="reload">重新加载素材管理</button></div><template v-if="!loading&&article&&!invalidated"><div class="writing-admin-version"><strong>{{ article.draft.titleZh }}</strong><label>文章版本 <select :value="version" :disabled="busy" @change="changeVersion"><option v-if="article.publishedVersionId" :value="article.publishedVersionId">当前发布版（{{ article.publishedVersionId }}）</option><option v-if="article.draftVersionId!==article.publishedVersionId" :value="article.draftVersionId">当前草稿版（{{ article.draftVersionId }}）</option><option v-if="version!==article.draftVersionId&&version!==article.publishedVersionId" :value="version">指定历史版本（{{ version }}）</option></select></label></div><div class="writing-admin-grid"><aside class="writing-admin-list"><button class="button-secondary" type="button" :disabled="busy" @click="select()">新增素材</button><p v-if="!items.length" class="reader-rail-note">此版本尚无素材。</p><button v-for="item in items" :key="item.id" type="button" :aria-pressed="selected?.id===item.id" :disabled="busy" @click="select(item)"><strong>{{ item.draft.expression }}</strong><small>{{ {DRAFT:'草稿',PUBLISHED:'已发布',UNLISTED:'已下架'}[item.status] }} · 已发布 {{ item.revision }} 次</small></button></aside><form ref="form" class="article-editor" @invalid.capture="feedback.invalid" @submit.prevent="save"><h2>{{ selected?'编辑素材':'新增素材' }}</h2><p v-if="selected?.status==='PUBLISHED'" class="field-hint">公开页面继续显示上次发布内容，保存后请再次发布更新。</p><fieldset :disabled="busy"><div v-for="field in fieldNames" :key="field" class="reading-field"><label :for="`writing-${field}`">{{ labels[field] }}</label><input v-if="field==='sortOrder'" :id="`writing-${field}`" v-model.number="input.sortOrder" type="number" name="sortOrder" required min="0" max="9999" step="1" :aria-invalid="fieldErrors[field]?'true':undefined" :aria-describedby="`writing-${field}-error`" @input="feedback.changed(field)"><textarea v-else :id="`writing-${field}`" v-model="input[field]" :name="field" :rows="field==='exampleEn'||field==='exampleZh'?3:2" :maxlength="limits[field]" required :aria-invalid="fieldErrors[field]?'true':undefined" :aria-describedby="`writing-${field}-error`" @input="feedback.changed(field)" /><FieldError :id="`writing-${field}-error`" :message="fieldErrors[field]" /></div></fieldset><FormFeedback ref="panel" :message="formError" /><button v-if="conflict" type="button" class="button-secondary" :disabled="busy" @click="reload">重新加载最新素材</button><div class="reading-actions"><button class="button-primary" :disabled="busy">{{ busy?'正在处理…':'保存素材草稿' }}</button><template v-if="selected"><button class="button-secondary" type="button" :disabled="busy||dirty" @click="changeStatus(selected,'publish')">{{ selected.status==='PUBLISHED'?'发布素材更新':'发布素材' }}</button><button v-if="selected.status==='PUBLISHED'" class="button-secondary" type="button" :disabled="busy||dirty" @click="changeStatus(selected,'unpublish')">下架素材</button><button class="text-button" type="button" :disabled="busy||dirty" @click="changeStatus(selected,'archive')">归档素材</button></template></div><p class="field-hint">{{ dirty?'有未保存修改':'草稿已同步' }} · 发布前请校对内容，素材不会自动发布。</p></form></div></template><FormFeedback v-else-if="!loading" :message="formError" /></section></template>
